import morphJson from './morph.json'
import { QUARTERS, DROPPED, COASTAL, type Morph } from './morph-format.ts'
import type { Sprawl } from './sprawl.ts'

const morph = morphJson as Morph

// Everything below is read from src/morph.json (generated by `pnpm morph`);
// nothing is computed at load beyond scaling to the viewport.

// ─── Tunables ────────────────────────────────────────────────────────────────
const FLY_START = 0.12 // progress where LEDs start leaving the board
const FLY_DUR = 0.42 // per-LED flight length (in progress units)
const SPLIT_DUR = 0.08 // once every LED has landed, all split into their quarters together over this span

// Colours. Lit LEDs are data (yellow); unlit LEDs are basemap (grey). Same colours on the map.
const BG = [6, 6, 6]
const BLOCK = [18, 17, 16] // LED block housing
const OFF = [38, 36, 33] // unlit LED = basemap
const ON = [255, 204, 36] // lit LED = data (warm yellow)
const COAST = [74, 71, 65] // basemap dots on the coastline: a touch lighter than unlit LEDs

// ─── Helpers ─────────────────────────────────────────────────────────────────
export const clamp = (x: number, a = 0, b = 1) => Math.min(b, Math.max(a, x))
const lerp = (a: number, b: number, t: number) => a + (b - a) * t
export const smooth = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}
const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const mix = (a: number[], b: number[], t: number) => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)]
const rgb = (c: number[]) => `rgb(${c[0] | 0},${c[1] | 0},${c[2] | 0})`

const [BOARD_X, BOARD_Y] = morph.board
/** Progress at which the last LED has landed: the island is formed, still at board resolution. */
const LANDED_AT = FLY_START + Math.max(...morph.leds.map((l) => l[5])) + FLY_DUR
/** Progress at which the split is done: from here on, the frame IS the finished map. */
export const MAP_SETTLED_AT = Math.min(1, LANDED_AT + SPLIT_DUR)
const [ISLAND_X, ISLAND_Y] = morph.island

/** Lattice spacing P (px) and the screen box of the board at rest. Both board and island fit. */
export function boardBox(vw: number, vh: number) {
  const P = Math.min((vw * 0.9) / BOARD_X, (vh * 0.6) / BOARD_Y, (vw * 0.88) / ISLAND_X, (vh * 0.88) / ISLAND_Y)
  return { x: vw / 2 - (BOARD_X * P) / 2, y: vh / 2 - (BOARD_Y * P) / 2, w: BOARD_X * P, h: BOARD_Y * P, P }
}

/** The island's bounding box in grid units (its outermost tiles), relative to the screen centre. */
const ISLAND_BOUNDS = (() => {
  const xs = morph.leds.map((l) => l[3]), ys = morph.leds.map((l) => l[4])
  return { x0: Math.min(...xs) - 0.5, x1: Math.max(...xs) + 0.5, y0: Math.min(...ys) - 0.5, y1: Math.max(...ys) + 0.5 }
})()

/** The island's bounding box on screen (px), as drawn for a viewport of vw × vh. */
export function islandBox(vw: number, vh: number) {
  const { P } = boardBox(vw, vh)
  const { x0, x1, y0, y1 } = ISLAND_BOUNDS
  return { x: vw / 2 + x0 * P, y: vh / 2 + y0 * P, w: (x1 - x0) * P, h: (y1 - y0) * P }
}

// ─── Scene ───────────────────────────────────────────────────────────────────
type Particle = {
  tx: number; ty: number // LED on the board
  cx: number; cy: number // centre of its tile on the island
  ox: number; oy: number // this quarter's offset from the tile centre
  led: number // index of its LED (board colour = that LED's brightness)
  base: number[] // map colour when dead: basemap grey, lighter on the coast
  delay: number
  primary: boolean // first quarter of its LED: the one drawn on the board at rest
}
type Rect = { x: number; y: number; w: number; h: number }

export type Scene = ReturnType<typeof createScene>

/**
 * Departures-board title → dot map of Mallorca at twice the board's resolution.
 * The board stretches onto the island like a rubber sheet (neighbours stay
 * neighbours); each LED lands on one board-sized cell and splits into its quarters.
 * Colours on the map and on the board always reflect the given sprawl state
 * (see sprawl.ts), read at draw time, so several scenes can render one state.
 * `draw(p)` renders progress p ∈ [0, 1] once; nothing animates on its own.
 */
export function createScene(canvas: HTMLCanvasElement, sprawl: Sprawl) {
  const ctx = canvas.getContext('2d')!
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)')
  let dpr = 1
  let W = 0, H = 0
  let blocks: Rect[] = []
  let particles: Particle[] = [] // particle i ↔ sprawl cell i
  let B = 0 // board LED diameter (px)

  /** Scale the stored grid-unit morph to the viewport. */
  function build(vw: number, vh: number) {
    const { P } = boardBox(vw, vh)
    B = P * 0.72
    blocks = morph.blocks.map(([x, y, w, h]) => ({ x: x * P, y: y * P, w: w * P, h: h * P }))
    particles = []
    morph.leds.forEach(([bx, by, , tx, ty, delay, packed], l) => {
      let first = true
      QUARTERS.forEach(([dx, dy], k) => {
        const kind = (packed >> (2 * k)) & 3
        if (kind === DROPPED) return
        particles.push({
          tx: bx * P, ty: by * P,
          cx: tx * P, cy: ty * P, ox: dx * P, oy: dy * P,
          led: l, base: kind === COASTAL ? COAST : OFF,
          delay, primary: first,
        })
        first = false
      })
    })
  }

  // Current colours, from the sprawl state: the board LED (built quarters ÷ reference)
  // and the map dot (built = data yellow). Refreshed at the start of every draw.
  let bright = sprawl.ledBrightness()
  const ledColor = (q: Particle) => mix(OFF, ON, bright[q.led])
  const dotColor = (q: Particle, i: number) => (sprawl.isAlive(i) ? ON : q.base)

  // ─── Batched round LEDs ─────────────────────────────────────────────────────
  // Dots are grouped by colour into one path each and filled in one call.
  // Coordinates are relative to the screen centre.
  let batch = new Map<string, Path2D>()
  const quantKey = (c: number[]) => rgb(c.map((v) => Math.min(255, Math.round(v / 6) * 6)))

  function led(x: number, y: number, size: number, color: number[]) {
    const key = quantKey(color)
    let path = batch.get(key)
    if (!path) { path = new Path2D(); batch.set(key, path) }
    const cx = W / 2 + x, cy = H / 2 + y, r = Math.max(size / 2, 0.5)
    path.moveTo(cx + r, cy)
    path.arc(cx, cy, r, 0, Math.PI * 2)
  }

  function flush() {
    for (const [key, path] of batch) { ctx.fillStyle = key; ctx.fill(path) }
    batch = new Map()
  }

  function resize() {
    dpr = Math.min(devicePixelRatio || 1, 2)
    W = canvas.clientWidth
    H = canvas.clientHeight
    canvas.width = Math.round(W * dpr)
    canvas.height = Math.round(H * dpr)
    build(W, H)
  }

  /** LED block housings. `fade` 0 = visible, 1 = gone. */
  function drawBlocks(fade: number) {
    ctx.fillStyle = rgb(mix(BLOCK, BG, fade))
    for (const r of blocks) ctx.fillRect(W / 2 + r.x, H / 2 + r.y, r.w, r.h)
  }

  function drawBoard(fade: number) {
    drawBlocks(fade)
    for (const q of particles) if (q.primary) led(q.tx, q.ty, B, mix(ledColor(q), BG, fade))
    flush()
  }

  function drawMap(visibility: number) {
    particles.forEach((q, i) => led(q.cx + q.ox, q.cy + q.oy, B / 2, mix(BG, dotColor(q, i), visibility)))
    flush()
  }

  /** Render progress p (0 = board, 1 = map). */
  function draw(p: number) {
    bright = sprawl.ledBrightness()
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.fillStyle = rgb(BG)
    ctx.fillRect(0, 0, W, H)

    if (p <= 0.0005) return drawBoard(0)
    if (p >= 0.9995) return drawMap(1)
    if (reducedMotion.matches) {
      // Crossfade only, no moving LEDs.
      const c = smooth(0.35, 0.65, p)
      if (c < 1) drawBoard(c)
      if (c > 0) drawMap(c)
      return
    }

    // In between: housings fade; each LED flies to its tile as one dot. Once the whole
    // island has formed, every dot splits into its tile's quarters at once (half the
    // size, each with its own map colour).
    const blockFade = smooth(0.02, 0.16, p)
    const split = smooth(LANDED_AT, MAP_SETTLED_AT, p)
    if (blockFade < 1) drawBlocks(blockFade)
    particles.forEach((q, i) => {
      const t = clamp((p - FLY_START - q.delay) / FLY_DUR)
      const travel = ease(t)
      led(
        lerp(q.tx, q.cx, travel) + q.ox * split,
        lerp(q.ty, q.cy, travel) + q.oy * split,
        lerp(B, B / 2, split),
        mix(ledColor(q), dotColor(q, i), split),
      )
    })
    flush()
  }

  return { resize, draw }
}
